// measure-490-refs.mjs — GH-490 Chinese-8 pocket-ring measurement chain,
// COMPUTED (round-4). Two consecutive audit rounds failed on the hand-
// transcribed record's arithmetic (r1: 205 px datum misassignment; r2:
// closure range, obliquity propagation, drift label, throat-range copy),
// so the manifest's derived numbers are now GENERATED by this script:
// the ONLY hand-entered facts are the pixel reads and datum constants in
// the INPUT LITERALS block below, each with its source; everything else
// (px/mm scales, closure percentages, envelopes with propagated
// tolerances, drift percentages, derived spans) is printed with the work
// shown. The sign-off pack carries a byte-identical copy at
// refs/measure.mjs beside refs/MANIFEST.md.
//
//   node web/tools/measure-490-refs.mjs           markdown GENERATED block
//   node web/tools/measure-490-refs.mjs --json    machine values (annotator
//                                                 input — the overlay labels
//                                                 come from here, never typed)
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

// ===================== INPUT LITERALS ===============================
// TPT Q8 pocket macro — PRIMARY frame (refs/tpt_q8_Pocket.jpg, 600×413,
// all reads @1×). Pixel reads = the round-3 annotation pass, drawn where
// they were taken in refs/audit_tpt_chain.png; that overlay is the ONE
// transcription source (the round-3 MANIFEST hand-copied "152–155" while
// the overlay said 153±3 — audit r2 blocking finding 1).
const TPT = {
  throatPx: { c: 153, tol: 3 }, // nose-to-nose cloth-jaw gap, luminance
  //   edges averaged across rows y 150–195
  rimWidthPx: 192, // fall-rim oval WIDTH, least-squares conic fit on 123
  //   boundary points (round-2 fit, re-used unchanged)
  hornGapPx: [205, 212.5], // leather horn-end inner edges,
  //   (180.5, 234) → (392.9, 228) — NO published datum (derived only)
  bandApexPx: [52, 57], // inner lip → crest, luminance-profile crest
  bandFlankPx: [58, 65], //   detection, rays every ~10°: apex / flanks
  phiDeg: [63, 84], // camera pitch bounds: visible skirt height (low) /
  //   near-circular net-hole fit, aspect 0.995 (high)
};
// Joy OFFICIAL Q8 macro — corroborating frame, RIM-LOCAL ruler only
// (refs/joy147_q8_pocket_macro.png, 1032×1032, reads @1×)
const JOY = {
  rimWidthPx: 356, // fall-rim WIDTH at the leather inner edges
  throatPx: 253, // nose-to-nose gap (lives in a FARTHER plane — close-up
  //   perspective; the cross-plane drift below is why no single scale
  //   transfers on this frame)
  bandPx: [74, 76], // inner lip → crest at the apex
  phiDeg: [40, 61], // pitch bounds carried honestly: net-hole read vs
  //   rim-oval transfer disagree; both endpoints kept
};
// 2025 Heyball Masters (Tianjin) press frame (refs/cdmasters_1.png) —
// crest corroboration ONLY (the band is near edge-on there; the round-2
// "30–50 coarse" band read stays demoted)
const MASTERS = { ballPx: 52, crestPx: [8, 12] };
// Q8 Pro side photo (refs/joy147_q8pro_pocket_side.png) — crest
// proudness as a scale-free ratio read against the rail line
const Q8PRO = { crestMm: [8, 12] };
// Datum constants
const MOUTH_MM = 85; // Joy official corner mouth (joy147.com Q8 spec)
const RIM_MM = { c: 105, tol: 1 }; // CBSA-circulating 角袋口内沿最短距离
//   (folk-spec family — cross-check datum only, never the sole ruler)
const BALL_MM = 57.15; // Chinese 8-ball hardware (2 1/4 in)
// Modeled ring geometry (web/scene/table.js, cn8 branch)
const MODEL = { bandMm: 33.5, crestMm: 10.0 };
// ====================================================================

const sin = (deg) => Math.sin((deg * Math.PI) / 180);
const r2 = (x) => Math.round(x * 100) / 100;
const r1 = (x) => Math.round(x * 10) / 10;
const pct = (x) => `${r2(x * 100)}%`;
// an envelope rounds OUTWARD to 0.1 mm — never clips its own interval
const outward = ([lo, hi]) => [Math.floor(lo * 10) / 10, Math.ceil(hi * 10) / 10];

// --- scales (px/mm), each datum's tolerance propagated -------------
const throatPxRange = [TPT.throatPx.c - TPT.throatPx.tol, TPT.throatPx.c + TPT.throatPx.tol];
const scaleA = throatPxRange.map((px) => px / MOUTH_MM); // datum A: 85 mm mouth
const scaleB = [TPT.rimWidthPx / (RIM_MM.c + RIM_MM.tol),
  TPT.rimWidthPx / (RIM_MM.c - RIM_MM.tol)]; // datum B: 105±1 mm rim
const centerA = TPT.throatPx.c / MOUTH_MM;
const centerB = TPT.rimWidthPx / RIM_MM.c;
// --- closure: do the two datum-scale intervals agree? ---------------
const overlapLo = Math.max(scaleA[0], scaleB[0]);
const overlapHi = Math.min(scaleA[1], scaleB[1]);
const intervalsOverlap = overlapLo <= overlapHi;
const centerDisagreement = Math.abs(centerB - centerA) / centerB;
const worstDisagreement = (Math.max(scaleA[1], scaleB[1]) - Math.min(scaleA[0], scaleB[0]))
  / Math.max(scaleA[1], scaleB[1]);
// the scale used for derived reads: the UNION of both datum intervals
// (conservative — the folk-spec cross-check never tightens the ruler)
const scaleU = [Math.min(scaleA[0], scaleB[0]), Math.max(scaleA[1], scaleB[1])];
// --- derived spans (no datum) ---------------------------------------
const hornGapMm = [TPT.hornGapPx[0] / scaleU[1], TPT.hornGapPx[1] / scaleU[0]];
// --- band radial extent: obliquity propagation ----------------------
// a radial pixel span foreshortens by sin(phi): mm = px / (scale · sinφ)
const bandPx = [Math.min(...TPT.bandApexPx, ...TPT.bandFlankPx),
  Math.max(...TPT.bandApexPx, ...TPT.bandFlankPx)];
const bandMmTPT = [bandPx[0] / (scaleU[1] * sin(TPT.phiDeg[1])),
  bandPx[1] / (scaleU[0] * sin(TPT.phiDeg[0]))];
// --- Joy macro: rim-local ruler + the cross-plane drift -------------
const joyRimScale = [JOY.rimWidthPx / (RIM_MM.c + RIM_MM.tol),
  JOY.rimWidthPx / (RIM_MM.c - RIM_MM.tol)];
const joyRimCenter = JOY.rimWidthPx / RIM_MM.c;
const joyThroatScale = JOY.throatPx / MOUTH_MM;
const driftVsThroat = (joyRimCenter - joyThroatScale) / joyThroatScale;
const driftVsRim = (joyRimCenter - joyThroatScale) / joyRimCenter;
const bandMmJoy = [JOY.bandPx[0] / (joyRimScale[1] * sin(JOY.phiDeg[1])),
  JOY.bandPx[1] / (joyRimScale[0] * sin(JOY.phiDeg[0]))];
// --- Masters press frame: ball ruler --------------------------------
const mastersScale = MASTERS.ballPx / BALL_MM;
const crestMmMasters = MASTERS.crestPx.map((px) => px / mastersScale);
// --- envelopes + model verdicts --------------------------------------
const bandEnvelope = outward(bandMmTPT); // PRIMARY frame propagation
const bandCorrob = outward(bandMmJoy);
const crestEnvelope = Q8PRO.crestMm; // scale-free primary read
const crestCorrob = outward(crestMmMasters);
const inside = (v, [lo, hi]) => v >= lo && v <= hi;
const verdict = {
  bandInsideEnvelope: inside(MODEL.bandMm, bandEnvelope),
  bandInsideCorrob: inside(MODEL.bandMm, bandCorrob),
  crestInsideEnvelope: inside(MODEL.crestMm, crestEnvelope),
  crestInsideCorrob: inside(MODEL.crestMm, crestCorrob),
};

const selfPath = fileURLToPath(import.meta.url);
const selfSha = createHash('sha256').update(readFileSync(selfPath)).digest('hex');

// keep every number raw here; formatting happens only at print time
const json = {
  scriptSha256: selfSha,
  literals: { TPT, JOY, MASTERS, Q8PRO, MOUTH_MM, RIM_MM, BALL_MM, MODEL },
  computed: {
    throatPxRange,
    scaleA, centerA, scaleB, centerB,
    intervalsOverlap, overlap: intervalsOverlap ? [overlapLo, overlapHi] : null,
    centerDisagreement, worstDisagreement, scaleU,
    hornGapMm, bandPx, bandMmTPT,
    joyRimScale, joyRimCenter, joyThroatScale, driftVsThroat, driftVsRim,
    bandMmJoy, mastersScale, crestMmMasters,
    bandEnvelope, bandCorrob, crestEnvelope, crestCorrob, verdict,
  },
};

if (process.argv.includes('--json')) {
  console.log(JSON.stringify(json, null, 2));
  process.exit(0);
}

const IN = (b) => (b ? 'INSIDE' : 'OUTSIDE');
console.log(`<!-- GENERATED:BEGIN — do not hand-edit; run refs/measure.mjs
     (byte-identical committed copy: web/tools/measure-490-refs.mjs,
     sha256 ${selfSha}) -->

## GENERATED measurement chain (round-4 — every number computed)

### Scales (TPT PRIMARY frame)

- Datum A — throat (nose) gap ${TPT.throatPx.c}±${TPT.throatPx.tol} px
  (${throatPxRange[0]}–${throatPxRange[1]} px) ↔ Joy official ${MOUTH_MM} mm mouth
  ⇒ **${r2(scaleA[0])}–${r2(scaleA[1])} px/mm** (center ${r2(centerA)}).
- Datum B — fall-rim oval WIDTH ${TPT.rimWidthPx} px ↔ CBSA-circulating
  ${RIM_MM.c}±${RIM_MM.tol} mm inner-edge datum
  ⇒ **${r2(scaleB[0])}–${r2(scaleB[1])} px/mm** (center ${r2(centerB)}).
- Closure: the two scale intervals ${intervalsOverlap
    ? `OVERLAP on [${r2(overlapLo)}, ${r2(overlapHi)}]` : 'DO NOT OVERLAP'};
  centers disagree by **${pct(centerDisagreement)}**; worst-case endpoint
  disagreement across both tolerance ranges **${pct(worstDisagreement)}**.
  (The round-3 hand-written "0.3–1%" compared cherry-picked endpoints —
  retracted.) Horizontal spans are obliquity-immune (both lie along the
  tilt axis).
- Derived scale for all mm conversions below: the UNION
  **[${r2(scaleU[0])}, ${r2(scaleU[1])}] px/mm** (conservative — the
  folk-spec cross-check never tightens the primary ruler).

### Derived spans (TPT)

- Leather horn-end gap ${TPT.hornGapPx[0]}–${TPT.hornGapPx[1]} px ⇒
  **${r1(hornGapMm[0])}–${r1(hornGapMm[1])} mm** (NO published datum —
  round-2 pinned "105 mm" here; that remains the retracted misassignment).

### Band radial extent (obliquity-propagated)

- TPT rays: apex ${TPT.bandApexPx[0]}–${TPT.bandApexPx[1]} px, flanks
  ${TPT.bandFlankPx[0]}–${TPT.bandFlankPx[1]} px ⇒ full read
  ${bandPx[0]}–${bandPx[1]} px. Radial mm = px / (scale × sin φ),
  φ ${TPT.phiDeg[0]}–${TPT.phiDeg[1]}° ⇒
  **${r2(bandMmTPT[0])}–${r2(bandMmTPT[1])} mm**
  (min: ${bandPx[0]}/(${r2(scaleU[1])}·sin${TPT.phiDeg[1]}°); max:
  ${bandPx[1]}/(${r2(scaleU[0])}·sin${TPT.phiDeg[0]}°)).
- Joy macro (corroborating; RIM-LOCAL ruler ${JOY.rimWidthPx} px ↔
  ${RIM_MM.c}±${RIM_MM.tol} mm ⇒ ${r2(joyRimScale[0])}–${r2(joyRimScale[1])}
  px/mm, center ${r2(joyRimCenter)}): band ${JOY.bandPx[0]}–${JOY.bandPx[1]} px
  over φ' ${JOY.phiDeg[0]}–${JOY.phiDeg[1]}° ⇒
  **${r2(bandMmJoy[0])}–${r2(bandMmJoy[1])} mm**.
- Joy macro cross-plane drift (why no single scale transfers there):
  throat ${JOY.throatPx} px / ${MOUTH_MM} mm = ${r2(joyThroatScale)} px/mm vs
  rim-local ${r2(joyRimCenter)} px/mm ⇒ **${pct(driftVsThroat)} relative to
  the throat scale / ${pct(driftVsRim)} relative to the rim scale** (the
  round-3 overlay's "18%" was an overstatement — retracted).

### Crest proudness

- Q8 Pro side photo, scale-free ratio read (PRIMARY):
  **${Q8PRO.crestMm[0]}–${Q8PRO.crestMm[1]} mm**.
- Masters press frame (corroborating): ball ruler ${MASTERS.ballPx} px /
  ${BALL_MM} mm = ${r2(mastersScale)} px/mm; crest ${MASTERS.crestPx[0]}–${MASTERS.crestPx[1]} px
  ⇒ **${r1(crestMmMasters[0])}–${r1(crestMmMasters[1])} mm** (coarse).

### Envelopes and the geometry verdict (computed)

- Band envelope (PRIMARY propagation, rounded outward):
  **${bandEnvelope[0]}–${bandEnvelope[1]} mm** — WIDER than the round-3
  hand-written "30–38" (which its own inputs did not support). Modeled
  **${MODEL.bandMm} mm** — **${IN(verdict.bandInsideEnvelope)}** (and
  ${IN(verdict.bandInsideCorrob)} the Joy corroborating
  ${bandCorrob[0]}–${bandCorrob[1]} mm).
- Crest envelope: **${crestEnvelope[0]}–${crestEnvelope[1]} mm**. Modeled
  **${MODEL.crestMm} mm** — **${IN(verdict.crestInsideEnvelope)}** (and
  ${IN(verdict.crestInsideCorrob)} the Masters corroborating
  ${crestCorrob[0]}–${crestCorrob[1]} mm).
- Round-1's 11 mm tube: the owner's "太窄" verdict stays
  measured-and-confirmed under every scale in the union.

<!-- GENERATED:END -->`);
